// Integration authoring packages, one per folder, for `integration add`:
// themes roots whose module graphs break in one way each, a component
// documented under another file's name, and namespace docs that a guide
// cannot be placed in.
import * as path from 'node:path';

const doc = (name, extra = '') => `/** @type {import('@astryxdesign/cli/authoring').ThemeDoc} */
export default {
  type: 'theme',
  name: '${name}',
  displayName: '${name}',
  description: 'The ${name} theme.',
  maintained: false,${extra}
};
`;

const built = (exportName, source = '') => `/**
 * @generated by \`astryx theme build\`${source ? `\n * Source: ${source}` : ''}
 */
export const ${exportName} = {name: 'x'};
`;

export default function (dir, {writeFile, writeJson}) {
  const pkg = (folder, manifest, files) => {
    const root = path.join(dir, folder);
    writeJson(path.join(root, 'package.json'), {name: `@sweep/${folder}`, version: '0.1.0'});
    writeFile(path.join(root, 'astryx.integration.mjs'), manifest);
    for (const [rel, text] of Object.entries(files)) writeFile(path.join(root, rel), text);
  };
  const themes = (folder, files) => pkg(folder, "export default {themes: './themes'};\n", files);

  themes('good', {
    'themes/good/goodTheme.doc.mjs': doc('good'),
    'themes/good/goodTheme.ts': "import {defineTheme} from '@astryxdesign/core/theme';\nimport {tokens} from './tokens';\n\nexport const goodTheme = defineTheme({name: 'good', ...tokens});\n",
    'themes/good/tokens.ts': 'export const tokens = {};\n',
  });
  themes('outside', {
    'themes/ref/refTheme.doc.mjs': doc('ref'),
    'themes/ref/refTheme.ts': "import {shared} from '../shared';\n\nexport const refTheme = shared;\n",
    'themes/shared.ts': 'export const shared = {};\n',
  });
  themes('selfdoc', {
    'themes/desc/descTheme.doc.mjs': doc('desc'),
    'themes/desc/descTheme.ts': "import meta from './descTheme.doc.mjs';\n\nexport const descTheme = {name: meta.name};\n",
  });
  themes('dynamic', {
    'themes/dyn/dynTheme.doc.mjs': doc('dyn'),
    'themes/dyn/dynTheme.ts': "export const dynTheme = {};\nexport const load = () => import('./missing');\n",
  });
  themes('typeonly', {
    'themes/ghost/ghostTheme.doc.mjs': doc('ghost'),
    'themes/ghost/ghostTheme.ts': "import type {ghostTheme} from './types';\n\nexport {ghostTheme};\n",
    'themes/ghost/types.ts': 'export type ghostTheme = {name: string};\n',
  });
  themes('reexport', {
    'themes/chain/chainTheme.doc.mjs': doc('chain'),
    'themes/chain/chainTheme.ts': "export {impl as chainTheme} from './impl';\n",
    'themes/chain/impl.ts': "import {defineTheme} from '@astryxdesign/core/theme';\n\nexport const impl = defineTheme({name: 'chain'});\n",
  });
  themes('unlisted', {
    'themes/hide/hideTheme.doc.mjs': doc('hide'),
    'themes/hide/hideTheme.ts': "export * from './.hidden';\n",
    'themes/hide/.hidden.ts': 'export const hideTheme = {};\n',
  });
  themes('broken', {
    'themes/bad/badTheme.doc.mjs': doc('bad'),
    'themes/bad/badTheme.ts': 'export const badTheme = {;\n',
  });
  themes('builtdoc', {
    'themes/brand/brand.doc.mjs': doc('brand'),
    'themes/brand/brand.js': built('brandTheme'),
    'themes/brand/brandTheme.ts': "import {defineTheme} from '@astryxdesign/core/theme';\n\nexport const brandTheme = defineTheme({name: 'brand'});\n",
  });
  themes('builtheader', {
    'themes/brand/brand.doc.mjs': doc('brand'),
    'themes/brand/brand.js': built('brandTheme', 'src/brandSource.ts'),
    'themes/brand/brandSource.ts': 'export const brandTheme = {};\n',
  });
  themes('builtnone', {
    'themes/brand/brand.doc.mjs': doc('brand'),
    'themes/brand/brand.mjs': built('brandTheme'),
  });
  themes('builtpair', {
    'themes/ocean/ocean.doc.mjs': doc('ocean'),
    'themes/ocean/ocean.ts': "import {defineTheme} from '@astryxdesign/core/theme';\n\nexport const ocean = defineTheme({name: 'ocean'});\n",
    'themes/ocean/ocean.js': built('oceanTheme'),
  });
  themes('twosources', {
    'themes/sea/seaTheme.doc.mjs': doc('sea'),
    'themes/sea/seaTheme.ts': 'export const seaTheme = {};\n',
    'themes/sea/seaTheme.mjs': 'export const seaTheme = {};\n',
    'themes/sea/seaTheme.jsx': 'export const seaTheme = {};\n',
  });

  pkg('documented', "export default {components: './src/components'};\n", {
    'src/components/Misc/Things.tsx': 'export function Shiny() { return null; }\n',
    'src/components/Misc/Things.doc.mjs': "export default {type: 'component', name: 'Shiny', category: 'Layout', usage: {description: 'Shiny.'}, props: []};\n",
  });
  pkg('namespaces', "export default {docs: './docs'};\n", {
    'docs/guides/acme.doc.mjs': "export default {type: 'namespace', name: 'acme', title: 'Acme', summary: 'Acme guides.', slots: {first: {title: 'First', accepts: {kinds: ['generic']}}, second: {title: 'Second', accepts: {kinds: ['generic']}}}};\n",
    'docs/none.doc.mjs': "export default {type: 'namespace', name: 'none', title: 'None', summary: 'No guide slot.', slots: {refs: {title: 'Refs', accepts: {kinds: ['reference']}}}};\n",
    'docs/broken.doc.mjs': "export default {type: 'namespace', name: 'broken', slots: {guides: {title: 'Guides', accepts: {kinds: ['generic']}}}};\n",
    'docs/one.doc.mjs': "export default {type: 'namespace', name: 'one', title: 'One', summary: 'One slot.', slots: {pages: {title: 'Pages', accepts: {kinds: ['generic']}}}};\n",
  });
  pkg('manifests', "export default {themes: './themes', agentDocs: 5, cliCommand: 'acme', bogus: true};\n", {});
  pkg('strmanifest', "export default 'nope';\n", {});
  pkg('arrmanifest', 'export default [1, 2];\n', {});
}
